class TestEdgeCases:
    """Verify behavior under unusual conditions."""

    def test_encoding_ascii_compatible(self, captured_stdout):
        """Output must be pure ASCII (no special characters)."""
        import hello
        output = captured_stdout.getvalue()
        # Ensure all characters are within ASCII range
        assert all(ord(c) < 128 for c in output), "Output must be ASCII-only"

    def test_no_side_effects_on_other_modules(self):
        """Importing hello should not modify other modules."""
        import sys
        before = set(sys.modules.keys())
        import hello
        after = set(sys.modules.keys())
        new_modules = after - before
        assert new_modules == {'hello'}, f"Should only add 'hello', got {new_modules}"

    def test_import_idempotent(self):
        """Multiple imports should not cause errors."""
        import hello
        import hello as hello2
        assert hello is hello2, "Multiple imports must return same module object"

    def test_reload_consistency(self):
        """Reloading should produce identical output."""
        import hello
        import importlib
        
        # First import
        out1 = io.StringIO()
        old_stdout = sys.stdout
        sys.stdout = out1
        importlib.reload(hello)
        sys.stdout = old_stdout
        
        # Second reload
        out2 = io.StringIO()
        sys.stdout = out2
        importlib.reload(hello)
        sys.stdout = old_stdout
        
        assert out1.getvalue() == out2.getvalue(), "Reloads must produce identical output"


